// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

if (empty(inp.workflowId)) throw new Error('EFX E_VALIDATION: workflowId is required');
const wf = String(inp.workflowId).trim();
const action = String(inp.action || '').trim();
let fn, args;
if (action === 'cancel') { fn = 'n8n_cancelWorkflow'; args = [wf]; }
else if (action === 'bump') { fn = 'n8n_bumpWorkflow'; args = [wf, empty(inp.targetStep) ? '' : String(inp.targetStep)]; }
else if (action === 'updateHireDate') {
  if (empty(inp.newDate) || !/^\d{4}-\d{2}-\d{2}$/.test(String(inp.newDate))) throw new Error('EFX E_VALIDATION: newDate (yyyy-MM-dd) is required for updateHireDate');
  fn = 'n8n_updateHireDate'; args = [wf, String(inp.newDate)];
}
else throw new Error('EFX E_VALIDATION: action must be cancel | bump | updateHireDate (got "' + action + '")');
return [{ json: Object.assign({ fn, args, action }, passthru) }];
